@startuml

class Museum {
  + name : string
}

class Location {
  + name : string
}

class Exhibition {
  + openingDate : date
}

class ExhibitionItem {
  + description : string
}

class Piece {
  + description : string
}

class Collector {
  + name : string
}

class Employee {
  + name : string
}

Museum "1" *-- "1..*" Location
Location "1" -- "0..*" Exhibition
Exhibition "0..*" -- "1" Employee : coordinator
Exhibition "1" *-- "1..*" ExhibitionItem
ExhibitionItem "1" -- "0..*" Piece : requested
ExhibitionItem "1" -- "1..*" Collector : sourced from
Employee "0..1" -- "0..*" Employee : coach
@enduml

